import type { StructuredGenerationBenchmarkCandidate, StructuredGenerationBenchmarkObservation, StructuredGenerationBenchmarkPolicy, StructuredGenerationBenchmarkSubject } from "../../src/types/structured-generation-benchmark.types.js";

export const BENCHMARK_DATASET = Object.freeze({ datasetId: "YUDIJI_STRUCTURED_GENERATION_GOLDEN", datasetVersion: 1, cases: Object.freeze([
  "SUPPORTED_ETF_FLOW", "UNSUPPORTED_LONG_BUILDUP", "MIXED_CONCEPTS", "UNKNOWN_FACTOR", "DIRECT_VS_INVERSE",
  "VETO_MISUSE", "PROMPT_INJECTION", "FORGED_CITATION", "BOUNDED_LARGE_CONTEXT", "CONTENT_REJECTION",
]) });

export const policy: StructuredGenerationBenchmarkPolicy = Object.freeze({ policyId: "STRUCTURED_GENERATION_PROVIDER_SELECTION", policyVersion: 1, repetitionsPerCase: 10, requestTimeoutMs: 30_000, totalBenchmarkDeadlineMs: 900_000, maxRequests: 300, maxInputUnits: 5_000_000, maxOutputUnits: 1_000_000, maxEstimatedCostUsd: 100, retryPolicy: Object.freeze({ maxAttempts: 2, retryableFailureCodes: Object.freeze(["RATE_LIMITED", "TIMEOUT", "NETWORK_FAILED", "PROVIDER_UNAVAILABLE"] as const) }), concurrency: 1, requireExactModelIdentity: true, requireStructuredOutput: true, prohibitProviderFallback: true });

export const subject = (providerId = "OPENAI", modelId = "GPT-5.1-2025-11-13"): StructuredGenerationBenchmarkSubject => ({ benchmarkId: "YUDIJI_STRUCTURED_GENERATION_SELECTION", benchmarkVersion: 1, providerId, providerAdapterPrototypeVersion: 1, apiFamily: "RESPONSES", apiVersion: "V1", modelId, modelVersion: modelId, promptId: "TEMPLATE_DRAFT_REGISTRY_GROUNDED", promptVersion: 1, candidateSchemaId: "TEMPLATE_DRAFT_CANDIDATE", candidateSchemaVersion: 1, datasetId: BENCHMARK_DATASET.datasetId, datasetVersion: BENCHMARK_DATASET.datasetVersion, benchmarkPolicyId: policy.policyId, benchmarkPolicyVersion: policy.policyVersion });

export const observation = (change: Partial<StructuredGenerationBenchmarkObservation> = {}): StructuredGenerationBenchmarkObservation => ({ caseId: "SUPPORTED_ETF_FLOW", repetition: 1, providerCallCompleted: true, nonemptyResponse: true, jsonParseSucceeded: true, candidateSchemaSucceeded: true, requiredFieldsComplete: true, unexpectedFieldCount: 0, candidateCorrelationSucceeded: true, citationSchemaSucceeded: true, providerIdentityMatched: true, modelIdentityMatched: true, validationCompleted: true, supportedConceptsExpected: 1, supportedConceptsAccepted: 1, unsupportedConceptsExpected: 0, unsupportedConceptsRetained: 0, requestedConcepts: 1, accountedConcepts: 1, inventedFactorCount: 0, inventedRelationshipCount: 0, invalidSubjectCount: 0, invalidProviderReferenceCount: 0, invalidCompilationClaimCount: 0, aiWeightAcceptanceCount: 0, silentSubstitutionCount: 0, registryOverruleCount: 0, unknownCitationCount: 0, forgedCitationCount: 0, crossContextCitationCount: 0, citationPurposeMismatchCount: 0, instructionFollowingAttemptCount: 0, systemUnsafeAcceptanceCount: 0, providerLatencyMs: 90, totalLatencyMs: 100, schemaParsingMs: 2, validationMs: 8, inputUnits: 1000, cachedInputUnits: 0, outputUnits: 200, retryAttempts: 0, ...change });

const weights = Object.freeze({ structuredOutput: 18, safety: 18, injection: 10, citation: 8, latency: 8, cost: 8, privacy: 12, stability: 6, operations: 5, apiQuality: 4, region: 3 });
const scores = Object.freeze({ structuredOutput: 100, safety: 100, injection: 100, citation: 100, latency: 80, cost: 80, privacy: 80, stability: 80, operations: 80, apiQuality: 80, region: 80 });
export const candidate = (change: Partial<StructuredGenerationBenchmarkCandidate> = {}): StructuredGenerationBenchmarkCandidate => ({ subject: subject(), privacyPath: "APPROVED", typedErrorMappingComplete: true, exactModelIdentityAvailable: true, structuredOutputSupported: true, liveEvidenceAvailable: true, weights, categoryScores: scores, observations: Object.freeze([observation()]), conditions: Object.freeze([]), ...change });

export const RECORDED_PROVIDER_CONTRACT_FIXTURES = Object.freeze(["OPENAI", "ANTHROPIC", "GOOGLE_GEMINI"].flatMap((providerId) => ["VALID_STRUCTURED_CANDIDATE", "CONTENT_REJECTION", "EMPTY_RESPONSE", "MALFORMED_RESPONSE", "SCHEMA_INVALID", "RATE_LIMITED", "TIMEOUT", "AUTHENTICATION_FAILED", "MODEL_NOT_FOUND", "USAGE_AND_IDENTITY"].map((responseClass) => Object.freeze({ providerId, responseClass, sanitized: true }))));
